const express = require('express');
const { param, validationResult } = require('express-validator');
const knex = require('knex')({ client: 'pg', connection: process.env.DB_URL });

const app = express();

const deleteRecordValidation = [
  param('zoneId').isUUID().withMessage('zoneId must be UUID'),
  param('recordId').isUUID().withMessage('recordId must be UUID')
];

app.delete('/api/v2/dns/zones/:zoneId/records/:recordId', deleteRecordValidation, async (req, res) => {
  if (!req.user || !req.user.organizationId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { zoneId, recordId } = req.params;

  // Verify the zone is owned by caller's organization
  const zone = await knex('dns_zones')
    .where({ id: zoneId, organization_id: req.user.organizationId })
    .first();

  if (!zone) {
    return res.status(403).json({ error: 'Access denied to this DNS zone' });
  }

  const deleted = await knex('dns_records')
    .where({ id: recordId, zone_id: zoneId })
    .del();

  if (!deleted) {
    return res.status(404).json({ error: 'Record not found in this zone' });
  }

  res.json({ success: true, deletedRecordId: recordId });
});

app.listen(6003);
